style.css:
@-moz-document regexp(".*tl.rulate.ru/book/.*") {
:root {
    --colorLight: #444444;
    --colorDark: #c9c9c9;
    --backgroundColorLight: #faf8f2;
    --backgroundColorDark: #000000;
    --fontSize: 20px;
    --maxWidth: 80%;
    --lineHeight: 26px;
    --fontFamily: Arial sans-serif;
  }


  #reader .text-wrapper {
    max-width: var(--maxWidth) !important;
  }

  body:not(.brightness-1) #reader,
  body:not(.brightness-1) #readpage .content-text * *,
  body:not(.brightness-1) header {
    background-color: var(--backgroundColorLight) !important;
    color: var(--colorLight) !important
  }

  .brightness-1 #reader #text-container p,
  .brightness-1 #reader #text-container blockquote,
  .brightness-1 #reader #text-container div,
  .brightness-1 #reader #text-container p span {
    background-color: var(--backgroundColorDark) !important;	
    color: var(--colorDark) !important
  }

  #readpage .content-text * {
    font-family: "var(--fontFamily)", serif !important;
    font-size: var(--fontSize) !important;
    line-height: var(--lineHeight) !important;
  }

  .brightness-1 #reader #text-container a span {
    color: #000 !important;
  }
}
